-- NaCCA curriculum for Basic 4 (part 1 of 2): 204 indicators (Computing, Creative Arts, English Language).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 4.
delete from public.curriculum_items
 where lower(class_name) = 'basic 4' and subject_key in ('computing', 'creative arts', 'english');

