insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B4.1.1.1', 'Identify parts of a computer and technology tools', 'B4.1.1.1.1', 'Identify parts of a computer and technology tools (the mouse, keyboard, monitor, system unit and its components (memory, h a r d d i s k d r i v e , C D - R O M e t c', ') , s p e a k e r s , a n d p e r i p h e r a l s . Bring items such as memory(i.e. memory cards, memory sticks),hard disk drive, CD-ROM etc. or pictures of these items to class and ask the learners to label selected items or computer parts in their note books.', 10),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B4.1.1.1', 'Identify parts of a computer and technology tools', 'B4.1.1.1.2', 'Describe the types of input devices of a computer and their uses', 'E.g. joystick, light pen, mouse, pointing stick etc. Bring input devices to class. Guide learners to explore the types of input devices and their uses.', 20),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B4.1.1.1', 'Identify parts of a computer and technology tools', 'B4.1.1.1.3', 'Differentiate between RAM and ROM', 'Bring a RAM or ROM to class or a picture of RAM and ROM to class. Guide learners to differentiate between ROM and RAM.', 30),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B4.1.1.1', 'Identify parts of a computer and technology tools', 'B4.1.1.1.4', 'Type short phrases. Guide learners to type different phrases using any Word Processing Application', null, 40),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B4.1.1.1', 'Identify parts of a computer and technology tools', 'B4.1.1.1.5', 'Summarise the first generation of computers which used vacuum tubes as a major piece of technology. Guide learners to discuss about the first generation of computers', 'e.g. ENIAC, EDVAC, UNIVAC, IBM-701 etc.', 50),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.1', 'Describe the desktop background and explain its features (', 'e.g. image, icons and Taskbar of the background). NB. This is to help the learner with software knowledge such as in office applications. Guide learners to explore the desktop background and explain its features (i.e. wallpaper, icons of files and folders you have or may have saved to the desktop, taskbar etc.). Show different desktop background images to learners. Assist them to explain its features.', 60),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.2', 'Demonstrate how to Personalise the Desktop Background using required tools and settings; Show projected examples of personalised Desktop Background to learners with the aid of a projector or pictures', 'Guide learners to personalise the Desktop Background using the required tools and settings.', 70),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.3', 'Demonstrate the use of the Sections of the Taskbar; Start Menu (Location and Launching only), Pinned Applications (Launched / Minimised programmes) and Notification Area or system tray (Date & Time, and Volume)', 'Guide learners to explore the use of the Taskbar, Start Menu, and Pinned Applications and Notification Area.', 80),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.4', 'Adding and removing icons from the desktop', 'Guide learners to add and remove icons from the desktop', 90),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.5', 'Moving, selecting and hiding multiple icons on the desktop', 'Guide learners to move, select and hide icons on the desktop.', 100),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer.)', 'B4.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B4.1.2.1.6', 'Creating, naming and renaming a folder. Guide learners to create, name and rename a folder. NB', '1. Learners can practice with the keyboard only in the absence of the applications.; 2. Learners should be guided to play computer games to re- enforce keyboard and mouse skills.', 110),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.1', 'Identify Data and collect data from different sources', 'B4.1.3.1.1', 'Use strategies for identifying data in conversation and newspapers. Guide learners to discuss strategies, which can be used to identify data and information. Use different approaches to aid identify data in conversation and newspaper', 'e.g. grouping students, role play etc.', 120),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.1', 'Identify Data and collect data from different sources', 'B4.1.3.1.2', 'Use strategies for classifying data into information (i.e. sorting and classifying) Guide learners to identify and record data in the different forms (', 'e.g. age, shoe size, etc.) Assist learners to extract and classify the relevant data into information.', 130),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.1', 'Identify Data and collect data from different sources', 'B4.1.3.1.3', 'Identify primary sources of information (photographs, audio recordings, video recordings, film, letters and diaries, speeches, published books, newspapers and magazines, government publications, oral histories, etc.) Guide learners in groups to discuss where one can get data and information and make a presentation on it to the class', null, 140),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.1', 'Identify Data and collect data from different sources', 'B4.1.3.1.4', 'Demonstrate Sending and sharing information to and from other gadgets', 'e.g., radio, fax, telephones calls, SMS etc. Guide learners to mention or talk about where one can receive or share information in the community and the world as a whole. NB: recall content in B3 and add to this activity.', 150),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.1', 'Identify Data and collect data from different sources', 'B4.1.3.1.5', 'Demonstrate basic calculations on sample data', 'e.g. sum, percentage, average etc. Guide learners to perform basic calculations on sample data they have been made to collect using sum, average, percentages etc. NB: This is to help the learner with fundamental principles of problem- solving in computing and Computer science.', 160),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.2', 'Demonstrate data collection using Data collection tools. CONTI’D', 'B4.1.3.2.1', 'Identify the steps and issues involved in data collection', 'Guide learners to explore I. the steps and issues involved in collection of data: a) identify the reason(s) for collecting data. b) select from the list of reasons for collecting the data and set goals. c) plan an approach and methods to collecting data and d. collect the data and interpret the data II. the issues involved in collection of data: a) Unavailability of data b) Intentional manipulation of data c) Random errors etc.', 170),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.2', 'Demonstrate data collection using Data collection tools. CONTI’D', 'B4.1.3.2.2', 'Describe various tools or techniques of data collection', 'e.g. interview, observation, checklist etc. Guide learners to explore the tools for collecting data and aid them to make practical examples of the various tools.', 180),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Data, Sources and Usage', 'B4.1.3.2', 'Demonstrate data collection using Data collection tools. CONTI’D', 'B4.1.3.2.3', 'Draw or sketch maps of the area to be surveyed', 'Bring diagrams or pictures of area(s) surveyed. Guide learners to sketch maps of an area to be surveyed by them.', 190),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Technology in the Community (communication)', 'B4.1.4.1', 'Demonstrate the use of technology in the community', 'B4.1.4.1.1', 'Describe how digital systems are used and could be used at home, in school and the local community', 'Guide learners to mention and describe how digital systems (computers, mobile phones, megaphones etc.) are used and could be used at home, in school and the local community.', 200),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Technology in the Community (communication)', 'B4.1.4.1', 'Demonstrate the use of technology in the community', 'B4.1.4.1.2', 'Identify and list common examples of energy-efficient gadgets and techniques used in homes, in schools and in the local communities', 'e.g. using the appropriate energy-efficient gadgets - energy saving bulbs …, choosing the right appliances, cleaning your stove often (soot removal), reducing overall cooking time etc. Bring pictures of energy-efficient gadgets or devices to class e.g. energy saving light bulbs, energy-efficient cooking stoves, toilet water saver, solar chargers, energy saving shower heads etc. to class. Guide learners to discuss in groups of five or less and present to the whole class examples of energy-efficient devices and techniques.', 210),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Technology in the Community (communication)', 'B4.1.4.1', 'Demonstrate the use of technology in the community', 'B4.1.4.1.3', 'Describe how a range of digital systems (hardware and software) and their peripheral devices can be used for different purposes in the community', 'Guide learners to discuss in groups of three to five, the range of digital systems and their peripheral devices. How they can be used for different purposes in the community. Let learners present their findings to the class. NB: technological tools stated here should be different from those stated in B3.', 220),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Technology in the Community (communication)', 'B4.1.4.1', 'Demonstrate the use of technology in the community', 'B4.1.4.1.4', 'Identify technological changes in the community (', 'e.g. Using automated irrigation for farming, eco-friendly pesticides and manure, etc.) Guide learners to explore technological changes in the community or in the world. Let learners find examples of technological changes in the community or world around them. They should be encouraged to present their findings to the class.', 230),
('Basic 4', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint (tabs and Ribbons of Ms-powerpoint)', 'B4.2.1.1', 'Demonstrate the use of MS- PowerPoint', 'B4.2.1.1.1', 'Demonstrate the use of clipboard, slides, fonts, paragraph and editing in the ribbons under the home ribbons section', 'Guide learners to explore the use of the clipboard, slides, fonts, paragraph, and editing features in MS- PowerPoint under the Home tab.', 240),
('Basic 4', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint (tabs and Ribbons of Ms-powerpoint)', 'B4.2.1.1', 'Demonstrate the use of MS- PowerPoint', 'B4.2.1.1.2', 'Show a 3-slide presentation using clipboard, slides, fonts, paragraph and editing of the ribbons studied', 'Guide learners to prepare and present a prepared project or exercise using clipboard, slides, fonts, paragraph and editing of the ribbons studied their work in MS-PowerPoint to the class. NB: This is to help the learners with software knowledge in Ms PowerPoint, office applications to grasp the concept well', 250),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Word Processing (tabs and Ribbons of Word Processing)', 'B4.3.1.1', 'Demonstrate understanding of the use of word processing application', 'B4.3.1.1.1', 'Demonstrate how to use the clipboard, styles, fonts, paragraph and editing. Guide learners to use clipboard, styles, fonts, paragraph and editing in the Home Tab of MS', '–Word.', 260),
('Basic 4', 'Computing', 'computing', 'Word Processing', 'Introduction to Word Processing (tabs and Ribbons of Word Processing)', 'B4.3.1.1', 'Demonstrate understanding of the use of word processing application', 'B4.3.1.1.2', 'Illustrate the use of the clip board, styles, fonts, paragraph and editing', 'Guide learners to use the clipboard, styles, fonts, paragraph and editing feature under the Home tab and let learners explore on a simple word document. NB. This is to help the learners with software knowledge in office applications (word processing) to grasp the concept better.', 270),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.1', 'Study and talk about visual artworks created by selected Ghanaian visual artists that reflect the history and culture of the people of Ghana', 'Study the visual artworks (e.g. wood carvings, printed fabrics, wall paintings, cartoons, posters, photographs, clay pots) created by some Ghanaian visual artists (such as Amon Kotei, Theodosia Okoh, Ablade Glover, Oku Ampofo, Offei-Nyako, Kwame Amoah, Betty Acquah, Kofi Antubam) by: a) gathering information from library books; surfing the internet;visiting art studios, galleries, museums or exhibitions; b) watching videos, films or observing photographs of artworks of some Ghanaian visual artists; c) examining some artworks of the artists to find out how those artworks reflect the history and culture of the people of Ghana. For example, relate the colours and star in the Ghana Flag to the history of Ghana; d) identifying and discussing symbols found in the artworks being studied that reflect the history and culture of the people of Ghana; e) writing brief notes about one visual artist using the following guidelines: - Name - Training - Type of artworks - Title of some works.', 10),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.2', 'Study and talk about visual artworks created by selected Ghanaian visual artists to generate ideas for designing and making own visual artworks', 'select an artwork of one of the visual artists studied;; think about the topic or purpose of that artwork. For example, flower pots/vases are made to hold flowers that decorate or beautify our surroundings;; examine the materials and production methods the artist used to design and make the selected visual artwork being studied. For example,', 20),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.3', 'Generate ideas by studying visual artworks created by selected Ghanaian visual artists that reflect the natural and manmade environments of some communities in Ghana', 'select artworks of some Ghanaian visual artists that show aspects of the natural and manmade environments;; observe the artworks in detail and describe the ideas that make up the artworks (e.g. the type of artwork, topic/purpose, natural and manmade things they show, art materials used);; assess the artworks by comparing their size, purpose, colours, ideas expressed, etc.', 30),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.4', 'Make decisions for designing and creating own visual artworks that will reflect the natural and manmade environments of some communities in Ghana', 'go on out-of-the-classroom walk to observe the natural and manmade surroundings;; collect samples of natural and manmade objects, take photographs, or make videos of objects that interest them;; examine the samples/pictures for their shapes, texture, colours, size, lines, etc. and gather ideas on artworks suggested;; reflect on the shapes, texture, colour, suggestions of movement, pattern, rhythm, etc. to generate ideas for designing and making own artworks.', 40),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.5', 'Develop ideas by studying the artworks of some Ghanaian visual artists that reflect topical issues in Ghana', 'select works of Ghanaian visual artists that exhibit current topical issues of national concern (e.g. road safety, plastic waste, water pollution, climate change, migration of youth);; share ideas on how the selected artworks express issues of national concern;; discuss the artworks by their type, topic/theme, materials used, style of artist, etc.', 50),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B4.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.1.1.1.6', 'Explore through brainstorming to generate ideas for creating own visual artworks that reflect topical issues in Ghana', 'learn about issues of national concern through library studies, watching films, surfing the internet, interviewing people, etc.;; document their findings by: a) writing simple notes and statements b) taking photographs and drawing pictures c) recording spoken words/voice messages, etc.;; discuss their findings in class with peers;; think about comments made by peers on their findings during class discussions;; use knowledge gained to generate ideas for designing and making own artworks that will reflect topical issues of national concern.', 60),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.1.2.2.1', 'Experiment with available visual arts media and methods to create artworks that express own views, knowledge and understanding of visual artworks that reflect the history and culture of the people in Ghana', 'explore the local environment to select available materials and tools that are suitable for making visual artworks;; practice the use of various visual arts media (e.g. tools, materials) using different methods of art making to try out how they work and make artworks (e.g. model with clay, weave with straw and paper, make prints with fingers and leaves);; assemble their test results and share their experiences through open discussion;; use available materials in the environment to make their own artworks based on ideas gathered from the visual artworks studied;; discuss and compare their artworks to the visual artworks studied.', 70),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.1.2.2.2', 'Experiment with available visual arts media and methods to create artworks that express own views, knowledge and understanding of the natural and manmade environments in some Ghanaian communities', 'explore the local environment to select available materials and tools that are suitable for making visual artworks;; study and test the use of available materials and tools by applying appropriate methods and skills: - clay, plasticine, papier mâché (paper pulp) etc. as material for modelling and casting; - straw, yarn, paper, etc. for weaving; - odds and ends for collage, constructing and assemblage; - brushes and paints for painting pictures; - pen knives for cutting, perforating, shaping; - paper for folding and creating mobiles, origami, kites; - spatula and scooping tools for modelling; - needles for sewing and stitching, etc.', 80),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.1.2.2.3', 'Experiment with available visual arts media and methods to create artworks based on own views, knowledge and understanding of topical issues in Ghana', 'explore the local surroundings to select available materials and tools that are good for making artworks;; study and experiment with available materials and tools using appropriate art making methods and skills e.g.: - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper etc. for weaving; - odds and ends for making mobiles and stabiles by constructing and assembling; - brushes and paint for painting; - spatula and scooping tools for modelling; - needle for sewing/stitching;; discuss and share their experiences through discussion and peer assessment;; use available materials in the environment to make own visual artworks that represent the artworks studied;; discuss and compare their artworks to the visual artworks studied.', 90),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, as well as the visual artists, their culture, the environment and current topical issues of concern in Africa', 'B4.1.2.3.1', 'Create own artworks using available visual arts media and methods to express own views, knowledge and understanding of the history and culture of the people of Ghana', 'select ideas from the history and culture of the people to come out with own designs; select and use available materials and tools and apply appropriate skills and techniques to make artworks based on their own designs. For example: - modelling with clay, plasticine, papier mâché (paper pulp) etc. to create a ceremonial pot, image of an ancestor etc. by pinching, slabbing, casting or modelling - weaving a tapestry, stole, fringe or tassel for decoration, wall hanging, etc. - creating an art form by constructing and assembling everyday materials such as containers: plastic bottles, packages etc. to create a decorative piece, etc. - drawing and painting images to honour personalities, for interior decoration, etc. - using paper/metal sheets to create forms in origami, quilling or filigree by punching, perforating, folding, trimming, etc. - artworks from fabric and leather by dyeing, sewing, printing, embossing, etc.; discuss and share their experiences through jury.', 100),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, as well as the visual artists, their culture, the environment and current topical issues of concern in Africa', 'B4.1.2.3.2', 'Create own artworks using available visual arts media and methods to express own views, knowledge and understanding of the natural and manmade environments of some Ghanaian communities', 'select ideas from the natural and manmade environments of some Ghanaian communities and create own designs for artworks (e.g. drawings, models, casting).; select and use available materials and tools as well as the application of appropriate skills and techniques to make artworks based on their own designs. For example: - modelling with clay, plasticine, papier mâché (paper pulp) etc. to create a functional, symbolic or decorative product etc. by pinching, slabbing, casting or modelling - weaving a symbolic, functional or decorative tapestry, stole, fringe or tassel, etc. - creating an art form by constructing and assembling everyday materials such as containers: plastic bottles, packages etc. to create a symbolic, functional or decorative pieces, etc.', 110),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making and Composing', 'B4.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, as well as the visual artists, their culture, the environment and current topical issues of concern in Africa', 'B4.1.2.3.3', 'Create own artworks using available visual arts media and methods to express own views, knowledge and understanding of performing artworks that reflect topical issues in Ghana', 'select ideas from topical issues that are currently trending in Ghana to develop own design concepts to educate or sensitize the public on the importance or dangers of those issues.; select and use available materials and tools as well as the application of appropriate skills and techniques to make artworks based on their own designs. For example: - modelling with clay, plasticine, papier mâché (paper pulp), etc. to create a functional, symbolic or decorative product etc. by pinching, slabbing, casting or modelling - weaving a symbolic, functional or decorative tapestry, stole, fringe or tassel, etc. - creating an art form by constructing and assembling everyday materials such as containers: plastic bottles, packages etc. to create a symbolic, functional or decorative pieces, etc. - drawing and painting images to illustrate ideas from the environment, create wall hangings, etc. - printing and organising images from natural and manmade sources to create decorative functional and symbolic artworks, etc. - use ideas from the environment to design and print fabric for decoration. - using paper/metal sheets to create forms in origami, quilling or filigree by punching, perforating, folding, trimming, etc. - creating artworks from fabric and leather by dyeing, sewing, printing, embossing, etc.', 120),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping artworks and inviting target audience for the planned display/performance', 'B4.1.3.4.1', 'Plan an exhibition of own artworks to share creative experiences based on own ideas, knowledge and understanding of the history and culture of the people of Ghana', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service;; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date; - selecting a venue; - inviting an audience;; brainstorm to agree on a theme for the exhibition;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience such as parents, PTA/SMC members, stakeholders, colleague learners);; select works for the exhibition by considering criteria like creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance;; decide on mode of display (e.g. hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post-exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 130),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping artworks and inviting target audience for the planned display/performance', 'B4.1.3.4.2', 'Plan an exhibition of own artworks to share creative experiences based on own ideas, knowledge and understanding of visual artworks that reflect the natural and manmade environments of some Ghanaian communities', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service;; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date; - selecting a venue; - inviting an audience;; brainstorm to agree on a theme for the exhibition;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners;; select works for the exhibition by considering criteria like creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance;; decide on mode of display (e.g. hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 140),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping artworks and inviting target audience for the planned display/performance', 'B4.1.3.4.3', 'Plan an exhibition of own artworks to share creative experiences based on own ideas, knowledge and understanding of topical issues in Ghana', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service).; discuss the need for displaying portfolio of own visual artworks.; develop a roadmap for the exhibition by: - fixing a date, - selecting a venue, - inviting an audience;; brainstorm to agree on a theme for the exhibition;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners;.; select works for the exhibition by considering (e.g. creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance);; decide on mode of display (e.g. hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 150),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B4.1.3.5.1', 'Display own artworks to share creative experiences based on own ideas, knowledge and understanding of the history and culture of the people of Ghana', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best tell the story of the history and culture of the people of Ghana);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits; label the works using manual penmanship (calligraphy) or ICT (computer) prints (e.g. name of artist, title of work, size of work, date of production).; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully (e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors books); NOTE; check/monitor visitors from improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition;; prepare template for appreciating, appraising, evaluating and reporting;; clean the hall after the exhibition.', 160),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B4.1.3.5.2', 'Display own artworks to share creative experiences based on own ideas, knowledge and understanding of the natural and manmade environments of some communities in Ghana', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best reflect the natural and manmade environment of some communities of Ghana);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual penmanship (calligraphy) or ICT (computer) prints: name of artist, title of work, size of work, date of production; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully, e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors books. NOTE; check/monitor visitors to prevent improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition;; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 170),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B4.1.3.5.3', 'Display own artworks to share creative experiences based on own ideas, knowledge and understanding of topical issues in Ghana', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best reflect current topical issues of national concern in Ghana);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual penmanship (calligraphy) or ICT (computer) prints: name of artist, title of work, size of work, date of production;; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully, e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors’ books; NOTE; check/monitor visitors improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition;; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 180),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.1.4.6.1', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the history and culture of the people of Ghana', 'discuss and accept a guide for appreciating and appraising own and/or others visual artworks based on the guidelines suggested below.;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines:; Description of the work: the elements in the work (dot, lines, shapes, forms, colour, texture, tone), materials used (paper, pencil, clay, wood), size of the work, number of objects/items in the work;; Subject matter: meaning, message, topic, mood, feelings, history, religion, environment, global warming;; Appraisal: what the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation connectional to other areas of learning;; Experiences to share: the design process through thinking and composing, planning and making, displaying and sharing, etc.', 190),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.1.4.6.2', 'Develop guidelines for appraising and appreciating own and others’ visual artworks that reflect the natural and manmade environments of some communities in Ghana', 'discuss and accept a guide for appreciating and appraising own and/or others visual artworks;; based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it', 200),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.1.4.6.3', 'Develop guidelines for appraising and appreciating own and others’ visual artworks that reflect topical issues in Ghana', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines:; Description of the work: the elements in the work (e.g. dots, lines, shapes, forms, colour, texture, tone), materials used (e.g. paper, pencil, clay, wood), size of the work, number of objects/items in the work;; Subject matter: meaning, message, topic, mood, feelings, history, religion, environment, global warming;; Appraisal: what the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation (connecting to other areas of learning);; Experiences to share: the design process through thinking and composing, planning and making, displaying and sharing, etc.', 210),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B4.1.4.7.1', 'Analyse and appreciate own and others’ visual artworks based on the developed guidelines and present own reports as feedback on the artworks that reflect the history and culture of the people of Ghana', 'display (real/photographs/video) selected works (own or that of others) that reflect the history and culture of the people of Ghana;; talk about the works dispassionately using the developed guidelines; ; use the outcome of the appreciation/appraisal to modify the product or to produce  similar or different artworks;; record/document the activity and share using a social media platform accepted by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 220),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B4.1.4.7.2', 'Analyse and appreciate own or others’ visual artworks based on the developed guidelines and present own reports as feedback on artworks that reflect the natural and manmade environments of some communities in Ghana', 'display (real/photographs/video) selected works (own or that of others) that reflect the natural and manmade environment of some communities in Ghana;; talk about the works dispassionately using the developed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or different artwork.; record/document the activity and share using a platform accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 230),
('Basic 4', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B4.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B4.1.4.7.3', 'Analyse and appreciate own or others’ visual artworks using the developed guidelines and present own report as feedback on artworks that reflect topical issues in Ghana', 'display (real/photographs/video) selected works (own or that of others) that reflect emerging topical issues in Ghana;; talk about the works dispassionately using the developed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce  similar or another artwork; ; record/document the activity and share using a platform accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 240),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.1', 'Study the performing artworks created by some Ghanaian performing artists that reflect the history and the culture of the people in Ghana', 'Study the performing artworks (music, dance, drama/play, poetry) composed or performed by some Ghanaian performing artists such as Ephraim Amu, Grace Omaboe, the National Dance Ensemble, Agya Koo Nimoh, Atukwei Okai by: a) gathering information from library studies, newspapers, surfing the internet, visiting performing art studios/location of performing arts groups, cultural centres, watching short videos/films, live/recorded performances, etc. of some Ghanaian performing artists; b) examining some performing artworks and sharing ideas about the compositions and performances studied on how those artworks reflect the history and culture of the people of Ghana; c) identifying and discussing the themes/topics of the compositions and performances that reflect the history and culture of the people of Ghana; d) writing notes about one performing artist using the following guidelines: - Name - Training - Type of compositions and performances - Title of some works.', 250),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.2', 'Generate ideas from the performing artworks of some Ghanaian performing artists studied for planning own compositions and performances that will reflect the history and culture of the people of Ghana', 'select a composition or performance of any of the Ghanaian performing artists studied;; think about the topic/theme or purpose of the work. For example, ‘Wɔgbɛdzɛkɛ’ by Nat Brew Amandzeba that traces the migration of the Ga people of Greater Accra region from Israel to their present location in Ghana;; study the words/lyrics, movement patterns and topics used by the artists in composing and performing their music, dance and drama (poetry/theatre);; generate ideas for composing and performing own music, dance, drama or poetry that will reflect the history and culture of the people of Ghana.', 260),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.3', 'Study the performing artworks created of some Ghanaian performing artists that reflect the natural and manmade environments of some communities in Ghana', 'select artworks of some Ghanaian performing artists that show aspects of the natural and manmade environments;; study the artworks in detail and describe the ideas that make up the artworks (e.g. the type of artwork, topic/purpose, ideas taken from natural and manmade things, instruments used, words/lyrics, etc.);; assess the artworks by comparing their types, topics/themes, purpose, function, ideas expressed, etc.', 270),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.4', 'Generate own ideas for composing and performing own artworks that will reflect the natural and manmade environments of some communities in Ghana', 'go on out-of-the-classroom walks to observe natural and manmade things in the surroundings;; observe the movement patterns of natural and manmade objects (e.g. animals, birds, trees, vehicles, bicycles, rims of tyres, people);; listen to sounds created by natural and manmade objects (e.g. moving vehicles, whistles, birds, flowing rivers/streams, drums, rain drops, wind);; record the movement and sounds of natural and manmade objects that interest the learners;; study and analyse the movements and sounds observed, listened to or recorded;; think about own collection of movement and sound patterns and use them to generate ideas for planning own music, dance, drama or poetry compositions and performances.', 280),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.5', 'Study the performing artworks of some Ghanaian performing artists that reflect topical issues in Ghana', 'select compositions and performances of some Ghanaian performing artists that reflect topical issues of national concern (e.g. road safety, plastic waste, water pollution, climate change, migration of youth);; discuss the compositions and performances to share ideas on how the selected artworks express topical issues of national concern in Ghana;; assess the artworks by comparing the types, topic/theme, materials used, style of artist, etc.', 290),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B4.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B4.2.1.1.6', 'Explore through brainstorming to develop ideas for creating own performing artworks that will reflect topical issues in Ghana', 'learn about issues of national concern from library books, newspapers, watching films, surfing the internet, interviewing people, etc.;; document their findings by: d) writing simple notes and statements; e) taking photographs and making videos; f) recording spoken words/voice messages, etc.; discuss their findings in class with peers;; think about comments made by peers on their findings during class discussions;; use knowledge gained to generate ideas for designing and making own performing artworks that will reflect current topical issues of national concern in Ghana.', 300),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.2.2.2.1', 'Experiment with available performing arts media and techniques to create artworks based on own views, knowledge and understanding of performing artworks that reflect the history and culture of the people of Ghana', 'explore the surroundings to select available instruments, sounds, rhythms, movement patterns, etc. that are suitable for composing and performing music, dance, drama, poetry, etc.;; experiment with available instruments, sounds, rhythms, movement patterns, etc. to perform some of the compositions of the Ghanaian performing artists studied that reflect the history and culture of the Ghanaian. For example, sing patriotic songs composed by Ephraim Amu, act parts of drama performed by Grace Omaboe or David Dontoh of Obra Drama Troupe, or recite poems created by Atukwei Okai or any local performing arts group;; discuss and share their experiences through peer review.', 310),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.2.2.2.2', 'Experiment with available performing arts media and techniques to create performing artworks based on own views, knowledge and understanding of the natural and manmade environments in some Ghanaian communities', 'explore the local surroundings to select available instruments, sounds, rhythms, movement patterns, etc. that are suitable for composing and performing music, dance, drama, poems, etc.;; experiment with the available instruments, sounds, movement patterns, melody, etc. to perform some compositions of some Ghanaian artists studied which reflect the natural and manmade environments of some communities;; discuss and share their experiences for peer review.', 320),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B4.2.2.2.3', 'Experiment with available performing arts media and techniques to create performing artworks based on own views, knowledge and understanding of topical issues in Ghana', 'explore the local environment to select available instruments, sounds, rhythms, movement patterns, etc. that are suitable for composing and performing music, dance, drama, poems, etc.;; experiment with the available instruments, sounds, movement patterns, etc. to perform some of the compositions of the Ghanaian artists studied that reflect topical issues of national concern in Ghana such as road safety, plastic waste, water pollution, low rainfall due to climate change, migration of youth, slums in cities;; discuss and share their experiences for peer review.', 330),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa as well as the visual artists, their culture, the environment and emerging topical issues', 'B4.2.2.3.1', 'Create own artworks using available performing arts media and techniques to express own views, knowledge and understanding of the history and culture of the people of Ghana', 'select ideas from the history and culture of the people and come out with own music, dance, drama, poem, etc.;; select and use available performing arts elements, instruments, movement patterns, and techniques to compose and perform own music, dance, drama, poetry, etc. based on their own concepts;; discuss and share their experiences through jury and peer review.', 340),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa as well as the visual artists, their culture, the environment and emerging topical issues', 'B4.2.2.3.2', 'Create own artworks using available performing arts media and techniques to express own views, knowledge and understanding of the natural and manmade environments of some Ghanaian communities', 'select ideas from the natural and manmade environments of some Ghanaian communities and come out with own music, dance, drama, poem, etc.;; select and use available performing arts elements, instruments, movement patterns, and techniques to compose and perform own music, dance, drama, poetry, etc. based on their own concepts;; discuss and share their experiences through jury and peer review.', 350),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B4.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa as well as the visual artists, their culture, the environment and emerging topical issues', 'B4.2.2.3.3', 'Create own artworks using available performing arts media and techniques to express own views, knowledge and understanding of performing artworks that reflect topical issues in Ghana', 'select ideas from topical issues that are trending in Ghana and create own music, dance, drama, poem, etc.;; select and use available performing arts elements, instruments, movement patterns, and techniques to compose and perform own music, dance, drama, poetry, etc. based on their own ideas;; discuss and share their experiences through jury and peer review.', 360),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B4.2.3.4.1', 'Plan a performance of compositions to share creative experiences based on own ideas, knowledge and understanding of the history and culture of the people of Ghana', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect the history and culture of the Ghanaian people;; discuss the need for performing compositions of own music, dance, drama, poetry, etc.;; develop a roadmap for the performances by: - fixing a date, - selecting a venue, - inviting an audience;; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners;; select compositions by considering e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props);; plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners, characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance;; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 370),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B4.2.3.4.2', 'Plan a performance of compositions to share creative experiences based on own ideas, knowledge and understanding of performing artworks that reflect the natural and manmade environments of some communities in Ghana', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect the natural and manmade environments of some communities in Ghana;; discuss the need for performing compositions of own music, dance, drama, poetry, etc.;; develop a roadmap for the performances by fixing a date, selecting venue and inviting audience; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners;; select compositions by considering creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props);; Plan the sequence of events, stage/site plan, identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel;; clean and prepare the venue and its environment and make it ready for the performance;; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 380),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B4.2.3.4.3', 'Plan a performance of own compositions to share creative experiences based on own ideas, knowledge and understanding of topical issues in Ghana Learners', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect current topical issues of national concern in Ghana.; discuss the need for performing compositions of own music, dance, drama, poetry, etc.; develop a roadmap for the performances by: - fixing a date, - selecting a venue, - inviting an audience;; brainstorm to agree on a theme for the performance;; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners;; select compositions by considering creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props).;; getting ready: plan the sequence of events, stage/site plan, identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corner), characters, directors, stage managers, audience, health and security ;personnel,; clean and prepare the venue and its environment and make it ready for the performance;; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 390),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/ manual/digital applications where necessary, to record for reporting on the events', 'B4.2.3.5.1', 'Perform own compositions to share creative experiences based on own ideas, knowledge and understanding of the history and culture of the people of Ghana', 'decide on the types and number of compositions to be performed during the event to reflect the history and culture of the people of Ghana based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show (e.g. explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day for opening, performances and closing. NOTE:; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 400),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/ manual/digital applications where necessary, to record for reporting on the events', 'B4.2.3.5.2', 'Perform own compositions to share creative experiences based on own ideas, knowledge and understanding of the natural and manmade environments of some communities in Ghana', 'decide on the types and number of compositions to be performed during the event to reflect the natural and manmade environments of some communities in Ghana based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully (e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show, explaining the concepts/title of the compositions and performances and the theme for the event, recording of comments and suggestions)', 410),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/ manual/digital applications where necessary, to record for reporting on the events', 'B4.2.3.5.3', 'Perform own compositions to share creative experiences based on own ideas, knowledge and understanding of topical issues in Ghana', 'decide on the types and number of compositions to be performed during the event to reflect current topical issues of national concern in Ghana based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully (e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show, explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing. NOTE:; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 420),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.2.4.6.1', 'Develop guidelines for appraising and appreciating own and others’ performing artworks that reflect the history and culture of the people of Ghana', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others compositions and performances on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines:; Music: theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music;; Dance: theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics; Drama: characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity, etc.', 430),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.2.4.6.2', 'Develop guidelines for appraising and appreciating own and others’ performing artworks that reflect the natural and manmade environments of some communities in Ghana', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guidelines suggested below.; identify the correct vocabulary to use for appreciating and appraising music, dance and drama;; agree on what to use the appraisal report for and how to share it', 440),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B4.2.4.6.3', 'Develop guidelines for appraising and appreciating own and others’ performing artworks that reflect topical issues in Ghana', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others compositions and performances on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines; Music: theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music;; Dance: theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics; Drama: characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity.', 450),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B4.2.4.7.1', 'Analyse and appraise own or others’ compositions and performances and present reports/feedback on works that reflect the history and culture of the people of Ghana', 'display (photographs/video) of selected performances (own or that of others) that reflect the history and culture of the people of Ghana; ; talk about the performances dispassionately using the developed guidelines; ; use the outcome of the appreciation/appraisal to modify the product or to produce similar or different composition and performance;; record/document the activity and share using a social media platform accepted by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 460),
('Basic 4', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B4.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B4.2.4.7.2', 'Analyse and appreciate/appraise own or others’ compositions and performances and present reports/feedback on works that reflect the natural and manmade environments of some communities in Ghana', 'display (photographs/video) of selected performances (own or that of others) that reflect the natural and manmade environments of some communities in Ghana; ; talk about the performances dispassionately using developed guidelines; ; use the outcome of the appreciation/appraisal to modify the product or to produce similar or different composition and performance;; record/document the activity and share using a social media platform accepted by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 470),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Songs', 'B4.1.1.1', 'Demonstrate understanding of variety of songs', 'B4.1.1.1.1', 'Listen attentively to songs and sing them with appropriate stress, rhythm and actions', 'Identify a variety of familiar songs from learners’ background.; Lead learners to sing the songs with appropriate stress, rhythm and intonation.', 10),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Songs', 'B4.1.1.1', 'Demonstrate understanding of variety of songs', 'B4.1.1.1.2', 'Identify and discuss values in songs', 'Select suitable songs for listening, singing/recitation from learners’ background. e.g. - National Anthem - National Pledge - Ten Galloping Horses Came Through the Town; After they have listened to the songs and also sang them, lead them to identify and discuss the values in the songs.', 20),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Poems', 'B4.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B4.1.3.1.1', 'Recite poems with stress, rhythm and actions and interpret them in own their words', 'Perform a short poem as learners listen and observe.; Teach the key words in the poem in context.; Have them read it in small groups, pairs and individually.; Emphasise correct stress and rhythm.', 30),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Poems', 'B4.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B4.1.3.1.2', 'Identify and discuss values in poems', 'Have learners recite the poem learnt.; Put them in groups to discuss the values in the poem.; Have groups share their views with the whole class.; Engage learners in recitation for mastery.', 40),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Poems', 'B4.1.3.1', 'Appreciate poems and other pieces of literary materials', 'B4.1.3.1.3', 'Compose four-line poems', 'Explain the task.; Guide learners with examples to choose a suitable topic and contribute suitable lines to it.; Write learner’s contributions to the topic on the board.; Re-arrange sentences in a logical order to form a simple poem.; In turns, learners read the poem for enjoyment. Note: Learners should not be made to commit new poems to memory on the same day. (It should be spaced over a number of lessons).', 50),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B4.1.4.1', 'Respond to stories', 'B4.1.4.1.1', 'Retell stories sequentially, including key details', 'Tell/read a suitable story to the class e.g. “The Hawk and the Hen”.; Learners retell the story in detail.; Have learners identify the parts of the story as beginning part, middle part and ending part.; Through questioning, have learners discuss the various parts of the story i.e. beginning, middle and ending, as in the table below: Title................. What was the Where in the story What are the key event? did this event details of this event? happen? Beginning Middle Ending; Put learners into groups to discuss the central message of the story.; Have learners retell the story sequentially.', 60),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Story Telling', 'B4.1.4.1', 'Respond to stories', 'B4.1.4.1.2', 'Tell own stories', 'Invite learners to tell their own stories to the class.; Have the class discuss the elements in the stories told.; Where in the story did this event happen?; Beginning; Middle; Ending', 70),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B4.1.5.1', 'Perform stories B4.1.5.2: Talk about key issues in stories/sketches', 'B4.1.5.1.1', 'Role-play a story/play', 'Select a suitable story/play learners have heard or read e. g. Ananse and the Black Pot.; Have learners identify and discuss the characters and events/key issues in the play/story.; Guide learners to role-play the key characters in specific scenes.', 80),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Dramatisation and Role Play', 'B4.1.5.2', 'Perform stories B4.1.5.2: Talk about key issues in stories/sketches', 'B4.1.5.2.1', 'Identify moral values in sketches and relate them to real life situations', 'Have learners discuss the characters and events/key issues in the play.; Put learners into groups or pairs depending on the number of characters in the play/drama. Each group should have a leader.; Give scenarios (from the story/play) to groups and have members take up roles of the characters. Create dialogues for the sketch and have learners prepare to perform the sketch. Go round and provide support to groups.; Have groups take turns to perform their sketch in front of the class.; Lead the class with questions to talk about each sketch. They talk about what went well, what needs to be improved, suggest alternative ways of doing it better, the moral values and how they relate to life.', 90),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.1', 'Use culturally acceptable language for communication', 'B4.1.6.1.1', 'Describe/talk about objects, events, dates and time', 'Demonstrate the activity by describing a classroom object.; Learners give oral descriptions of classroom and other familiar objects such as a table, a school bag, a chair and others, (Learners may ask questions as the description goes on). Festivals; Learners name familiar festivals and talk about them: when they are held, why and how they are celebrated, etc. Birthdays; Learners state their birthdays/dates and write them down using the two formats indicated in the content. (Teacher should check accuracy). Telling the Time; Using a clock face, assist learners to revise telling the time using expressions such as half past 8, quarter past 8, quarter to 8, etc. Assist learners to tell the time throughout the day: 10 minutes past 8; 25 minutes past 9; 20 to 11 etc. Important places in the country; Provide a map of Ghana and assist learners to identify important places and talk about them.; Have learners locate these places on the map.', 100),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding', 'B4.1.6.2.1', 'Listen and view attentively and for a sustained period (', 'e.g., look at the person speaking) and maintain eye contact.; As learners observe and listen attentively, engage in a conversation with one of them on a topic e.g. “Important Places in the District”.; Repeat procedure in bullet one, above, in talking about names of regions/places, festivals, date, time, familiar objects, etc.; Pairs may be invited to perform in front of the class.', 110),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.2', 'Demonstrate positive listening and viewing attitudes and behaviour by showing attentiveness and understanding', 'B4.1.6.2.2', 'Listen and view for the entire duration of a text, a speech, a presentation, a video etc', 'Play a recorded speech by an important personality (e.g. the President) on a relevant topic.; Have learners listen to the speech carefully.; Each learner prepares a speech in an imagined or assumed position.; Working in groups, each learner delivers his/her speech to the group. Groups listen carefully during each delivery.', 120),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation', 'B4.1.6.3.1', 'Engage in collaborative conversation on topics such as myself, family, personalities etc. with peers', 'Model describing yourself: e.g. name, physical features, character, likes and dislikes etc.; Guide learners with appropriate questions to give oral descriptions of themselves.; Select and describe a family member using relevant vocabulary e.g. − sister/brother/parent – name, age − how he/she looks like – shape of face, facial marks if any, shape of nose, eyes, etc. − height, colour and any minute detail that can be used to identify the person easily.; Guide learners with questions and other activities, to mention the name of the Regional Minister for the region in which their school is located.; Have learners mention names of personalities in politics such as the Ministers for Education, Health, Agriculture, etc.; Through questions and answers have learners talk about the roles and duties of these ministers.; Individually, ask learners to talk about their favourite personalities in sports, music, and mention their characteristics, and what they like about the personalities mentioned. Note: Ensure that learners use descriptive words.', 130),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation', 'B4.1.6.3.2', 'Demonstrate turn taking in conversation on different topics and speak audibly, and express thoughts and feelings clearly', 'Demonstrate turn taking with a learner earlier prepared.; Learners in pairs, take turns to talk about given topics in groups observing turn taking.', 140),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Conversation - Talking about Oneself, Family, People, Customs, Social/Cultural Values and Manners', 'B4.1.6.3', 'Use knowledge of language and communicative skills to participate in conversation', 'B4.1.6.3.3', 'Ask relevant questions to find out the opinion of others about a given topic', 'Demonstrate the activity using a familiar topic.; Learners ask and answer questions for clarification about what other learners say on a given topic.', 150),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B4.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B4.1.7.1.2', 'Make connections with events in narrative texts', 'Learners retell the story (e.g. in a chain).; Guide learners to identify the events in the story.; Put learners in small groups to discuss the events of the story and relate them to one another.', 160),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B4.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B4.1.7.1.3', 'Recognise and discuss moral lessons in a story', 'Through brainstorming, learners identify, discuss and evaluate moral lessons in narrative texts heard/read.; Have them connect to the characters by relating them to real life experiences.', 170),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B4.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B4.1.7.1.4', 'Use background knowledge to aid in understanding and building new knowledge while listening to narrative texts', 'Have learners listen to a narrative text.; Learners in groups identify, discuss and relate the plot of the text to a familiar text.; Have learners listen to the text a second time.; In groups, learners share what they have learnt in the text.', 180),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B4.1.7.1', 'Use appropriate skills and strategies to process meaning from texts', 'B4.1.7.1.5', 'Identify the main idea/gist and details of texts', 'Have learners read short stories, newspaper cuttings.; Guide them with examples to give the gist and details of the texts.; Guide learners to identify the various text contents as they retell and discuss texts read.; Assist learners to identify themes from the various texts read or discussed. e. g. love, greed, honesty, hard work, etc.; Have them share facts from the story with their peers.', 190),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Listening Comprehension', 'B4.1.7.1', 'Use appropriate skills and strategies to process meaning from texts CONT’D', 'B4.1.7.1.7', 'Compare and contrast information (two or more ideas) from texts', 'Guide learners to compare and contrast the content of different texts read/discussed (pay attention to the differences and the similarities).', 200),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B4.1.8.1', 'Demonstrate understanding in asking and answering questions correctly', 'B4.1.8.1.1', 'Use appropriate pronunciation and intonation in asking and answering questions', 'Through role-play, learners ask questions such as: What is your name? How are you? Where do you live?; Guide learners to use appropriate pronunciation and intonation in asking and answering questions. e.g. What do you want? Where’s your school? Note: A rising intonation for a question and a falling intonation for an answer.', 210),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Asking and Answering Questions', 'B4.1.8.2', 'Identify and use question tags correctly in speech CONT’D', 'B4.1.8.2.1', 'Use positive tags, negative tags and auxiliaries in speech', 'Discuss and explain what question tags are and give examples.; Learners in pairs ask and answer questions.; Demonstrate the usage of positive and negative tags.; Guide learners in oral practice to use positive and negative tags. e.g. Question: “You have a pen, don’t you?” Answer: Yes, I do. Answer: No, I don’t.; Use the internet to identify the appropriate intonation in asking and answering questions.; Through role play, learners demonstrate asking and answering questions.', 220),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B4.1.9.1', 'Use verbs appropriately in commands, requests and directions in speech', 'B4.1.9.1.1', 'Give and respond to commands, instructions and directions', 'Give general commands and guide learners to respond appropriately to the commands. e. g. Stand up! Sit down! Carry the bowl! etc.; Through role play, group and pair activities, assist learners to give and obey simple commands/instructions. e.g. i. Go to your seat. ii. Bring your exercise book to me. iii. Walk from B1 classroom to the Headmaster’s office iv. Turn right, walk twenty steps towards the water tank.', 230),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Giving and Following Commands/ Instructions/Directions and Making and Responding to Requests', 'B4.1.9.1', 'Use verbs appropriately in commands, requests and directions in speech', 'B4.1.9.1.2', 'Make and respond to polite requests for help from peers', 'Model making a request to learners.; Have learners work in groups to write three tasks they plan to do and need help with, e.g. do homework, carry the table, etc.; Learners then go around the class making requests to find classmates who are free to help them with their three tasks, e.g. “Can you please help me do my homework this afternoon?”. If a learner is free, they accept the request. But if s/he is not free, they decline the request.', 240),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.1', 'Show knowledge of spoken grammar and register', 'B4.1.10.1.1', 'Demonstrate awareness of the features of spoken language (contractions, ellipsis', 'e.g. A: How are you? B: Fine); Through role play, demonstrate the features of spoken language. e.g. Contractions: Can’t, Shouldn’t, etc. Ellipses: A. How are you? B. Fine.', 250),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.1', 'Show knowledge of spoken grammar and register', 'B4.1.10.1.2', 'Demonstrate awareness of the differences between spoken and written forms of language', 'e.g. simple and complex sentence structures', 260),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.1', 'Show knowledge of spoken grammar and register', 'B4.1.10.1.3', 'Demonstrate awareness of how meaning is conveyed through appropriate pace, stress, tone', '– through stories read aloud; Model reading aloud a level-appropriate story or a paragraph with good pace, stress or intonation.; Read the same story or text aloud with poor pace, stress and intonation.; Put learners into groups to analyse the types of reading and identify which one conveys meaning and why.; Have learners practise reading the story with good pace, stress and intonation.', 270),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation', 'B4.1.10.2.1', 'Speak clearly and fluently, using the appropriate voice qualities (pace, tone etc.)', 'Model a speech: choose a familiar topic and make a short speech on it.; Guide learners to discuss the speech.; Have learners practise in groups to select topics and make short speeches on them. Encourage them to speak clearly and fluently using the appropriate voice qualities.', 280),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.2', 'Demonstrate the ability to communicate with accurate pronunciation and appropriate intonation', 'B4.1.10.2.2', 'Read aloud clearly, at a good pace and with expression', 'Provide varied texts and guide learners to read them clearly at a good pace and with good expression. The texts can be in the form of poems/rhyme, etc.', 290),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.1', 'Identify the purpose and audience of a speech and set goals in the context of assigned topics (', 'e.g. about familiar persons); Using a model speech which must be provided by the teacher, guide learners to identify: i. the purpose of the speech; ii. the audience; iii. the goals set in the context of assigned topics. Note: The speech can be about self, familiar persons, objects and experiences.', 300),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.2', 'Draw on prior knowledge to identify the subject matter of a speech', null, 310),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.3', 'Gather and select facts and ideas from one or multiple print and/ or non-print sources, appropriate to the purpose, audience, context and culture', 'Guide learners to select interesting topics they want to talk about.; Put them into groups and have each group choose a topic.; Guide learners to gather ideas from their readers and/or online resources.', 320),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.4', 'Support ideas and points with visual resources to convey meaning appropriate to purpose and context', 'Have groups of learners draw pictures to support their ideas or points of view on given topics.', 330),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.5', 'Use effective introductions and conclusions', 'Put learners into convenient groups.; Guide them to select topics of interest, plan and present speeches to the class.; Guide them to introduce and conclude their speeches appropriately.', 340),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.6', 'Elaborate on ideas using explanations', 'Explain the need to elaborate on points made.; Present examples.; Guide learners to use details, concrete examples, to elaborate on their ideas/points of view on given topics.', 350),
('Basic 4', 'English Language', 'english', 'Oral Language', 'Presentation', 'B4.1.10.3', 'Plan and present information and ideas for a variety of purposes', 'B4.1.10.3.7', 'Speak with confidence before peers and maintain eye contact', 'Encourage learners doing presentations to speak before different audiences. e. g. small and large groups; Invite a learner and model maintaining eye contact while speaking with him or her. Have pairs of learners practise talking to each other on topics of interest while maintaining eye contact', 360),
('Basic 4', 'English Language', 'english', 'Reading', 'Phonics', 'B4.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B4.2.2.1.1', 'Match sounds to their corresponding letter/letter patterns (', 'e.g. initial/final consonants – m, j, f, s, etc., initial short vowels”– a, e, i, o, u”, final “y” as vowel, silent letters etc.); Introduce the sounds with alphabet songs or rhymes.; Guide learners to identify and produce the sounds of given letter patterns. e. g. Teacher: Make the sound as I point to each letter. (Learners begin with the initial/final consonants, initial short vowels, final y as vowel and silent letters).; In pairs/ groups, learners identify given letter patterns. Have learners apply their knowledge of consonant digraphs.', 370),
('Basic 4', 'English Language', 'english', 'Reading', 'Phonics', 'B4.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B4.2.2.1.2', 'Read single-syllable-words with taught consonant digraphs (sh-ship, ch-rich, ck-lock) and when reading continuous texts', null, 380),
('Basic 4', 'English Language', 'english', 'Reading', 'Phonics', 'B4.2.2.1', 'Connect sounds to letters; and blend letters/syllables in order to read and write', 'B4.2.2.1.3', 'Use words with consonant digraphs to make meaningful sentences', null, 390),
('Basic 4', 'English Language', 'english', 'Reading', 'Phonics', 'B4.2.2.2', 'Connect sounds to letters; and blend letters/syllables in order to read and write CONT’D B4.2.2.2: Use reading readiness and word identification skills', 'B4.2.2.2.1', 'Recognise and read words using a variety of cues (', 'e.g. prefixes – word beginning); Guide learners to understand that the core of a word is its root and that other words can be got by additions to a root word.; Guide learners to form more words using prefixes. e. g. a prefix may create new words. e.g. tell – retell over – moreover Note: Prefixes may create antonyms (opposites). e.g. friendly - unfriendly satisfied - dissatisfied; In groups, learners identify several prefixes and use them in sentences. PREFIX(before) ROOT(core) NEW WORD Mis Use misuse En Joy enjoy Anti Clockwise anticlockwise De Compose decompose Poly Clinic polyclinic Note: Prefixes have meanings of their own e.g. Ante–before, bi–two, ex–out of, previous, from etc.; ROOT(core); Use; Joy; Clockwise; Compose; Clinic', 400),
('Basic 4', 'English Language', 'english', 'Reading', 'Word Families, Rhyming Endings and Common Digraphs', 'B4.2.3.1', 'Identify rhyming/endings words and common digraphs', 'B4.2.3.1.1', 'Use common rhyming/ending words to decode words', 'e. g. at, pat, mat, fat, etc.; Revise the lesson on prefixes. Let learners know that just as we have family names (surnames), there are words that have the same ending that belong to the family of rhyming words.; Through brainstorming have learners come up with words that belong to a particular rhyming family. Have children identify these rhyming words as they read.; Have learners hunt for these words and build a portfolio on them.; Guide learners to build on words. e.g. –at = cat – bat – hat -all = call – fall – wall - it = sit – pit – hit -ot = tot – pot – cot', 410),
('Basic 4', 'English Language', 'english', 'Reading', 'Word Families, Rhyming Endings and Common Digraphs', 'B4.2.3.1', 'Identify rhyming/endings words and common digraphs', 'B4.2.3.1.2', 'Read words with digraphs to make meaningful sentences', 'Revise the lesson on prefixes.; Through brainstorming have learners come up with as many words that belong to a particular digraph. Have learners identify these digraphs as they read.; Have learners hunt for these words and build a portfolio on them. Ask learners to identify digraphs in simple sentences. e. g. The girls shouted. (sh as in shout) Note: Common digraphs include ch, ck, gh, gr, sch, sc; Learners form their own sentences using words with digraphs.', 420),
('Basic 4', 'English Language', 'english', 'Reading', 'Diphthongs', 'B4.2.4.1', 'Identify and use diphthongs to decode words', 'B4.2.4.1.1', 'Use closing diphthongs', 'e.g. /ei/, /ai/, /oi/ to make meaningful sentences; Teach one diphthong at a time.; Write words with each of the diphthongs on the board. Pronounce the words and have learners repeat after you.; Learners come up with examples of words that have the diphthongs.; Have learners identify these diphthongs as they read the words. E.g. ei - take oi - boy ai– why, try; Learners form their own sentences using words having diphthongs.', 430),
('Basic 4', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B4.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B4.2.5.1.1', 'Orally produce single-syllable words by blending sounds (phonemes), including consonant blends', 'Guide learners to play games like “Tapping Out” to bring out the single-syllable words.; Demonstrate blending by sounding out letters separately and blending/bringing them together into syllables and words. e.g. p-l-o-t = plot b-l-a-c-k = black g-r-o-w = grow; Have learners identify words containing particular blends e.g. bl, br, cr, cl, gr, gl Tapping Out Game “Tapping Out” is about using the fingers to teach decoding /blending the sound of letters.; Each finger represents a letter sound of single-syllable words.; Turn your back to the class and raise your right hand.; Raise the index finger straight as learners watch.; Bring the index finger down to meet the thumb as you make the sound.; Use fingers to demonstrate blending.', 440),
('Basic 4', 'English Language', 'english', 'Reading', 'Blends and Consonant Clusters', 'B4.2.5.1', 'Identify and use consonant blends and clusters in reading', 'B4.2.5.1.2', 'Use the spelling-sound correspondences for common consonant digraphs', 'Through discussion, have learners come up with many words that have a particular digraph.; Have learners decode these digraphs as they read.; Assist learners to get the spelling-sounds correspondence right. Play a game of the spelling-sound correspondence of selected digraphs. In groups, have learners sound out words and identify the digraphs in them. The group that gets a lot of this right carries the day. e.g. sh: shoe, show, shirt, shine, shell, shame, shake, shop, bush, wash, brush, marsh, crush, fish', 450),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.1', 'Understand word meanings and usages', 'B4.2.6.1.1', 'Use level-appropriate content words (nouns, verbs, adjectives and adverbs) and function words (prepositions) appropriately in spoken and written communication', 'Using examples, have learners see the difference between content and function words; Provide a substitution table of content words and function words for learners to construct sentences from. Help learners to sort out the different content words and function words in groups.; Assist learners to understand that these words combine into sentences to help us make proper meaning of them.; Let learners make sentences using function and content words.', 460),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.1', 'Understand word meanings and usages', 'B4.2.6.1.2', 'Use the following terms: compound word, idiom, simile, synonym, antonym, pre-fix, suffix, phrasal verb etc. in spoken and written expressions', 'Introduce the terms one at a time with several examples.; Elicit examples from learners.; Learners identify examples from different sources, e.g. their readers, story books, newspapers (Junior Graphic) and use them in sentences of their own.', 470),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.2', 'Build vocabulary B4.2.6.3: Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills', 'B4.2.6.2.1', 'Develop a rich vocabulary stock through extensive reading of age-appropriate texts', 'Introduce learners to a variety of story books and vocabulary portfolios and stress the need to build and use the new vocabulary in sentences.; Display some of the vocabulary in class, on your word trees and in sentences. Have learners work in pairs, individually and in groups, to do same.; Guide learners to make meaning from the context in which words have been used.', 480),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.3', 'Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills CONT’D B4.2.6.4: Use words appropriately for purpose, audience, context and culture', 'B4.2.6.3.1', 'Deduce meaning of words from how they are used in context', 'e.g. near synonyms: cool – cold – freezing), homonyms: flour/flower; Using several examples guide learners to make meaning from the context in which words have been used.(contextual meaning); Learners work in pairs and in groups to work out the meaning of given words from their context.', 490),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.3', 'Demonstrate a rich vocabulary that supports the development of listening, reading, speaking, writing and presentation skills CONT’D B4.2.6.4: Use words appropriately for purpose, audience, context and culture', 'B4.2.6.3.2', 'Deduce meaning of words from how they relate to one another (synonyms, antonyms)', 'Reverse the meaning of the terms using examples.; Have learners play games (e.g. Synonym Tree Game) to reinforce their knowledge of antonyms and synonyms.; Ask learners to find synonyms and antonyms of words made from context to build on their vocabulary.; Learners may match words with their synonyms/antonyms.', 500),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B4.2.6.4.1', 'Expand vocabulary stock through affixation', 'Revise prefixes and suffixes by breaking down some common words into their roots- prefix/suffix components. e.g. happy + ness = happiness un + happy + ness = unhappiness; Guide learners to play games, e.g. Affixes Game. Write prefixes and suffixes on cards. Learners take turns to pick these from the basket or bag. If a learner is able to add a root to the prefix or the suffix and read out the word correctly, he/she keeps it. At the end of the game, the child with the largest number of cards wins the game.; Learners may also work in groups to derive words using given prefixes and suffixes and using them in sentences.', 510),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B4.2.6.4.2', 'Recognise the playful use of words in spoken and written language (jokes, riddles)', 'In pairs/ groups, have learners play on words in educative jokes, riddles and puns. e.g. Riddle, Riddle: I am something that came into this world with earrings. Who am I? Answer: Coal pot', 520),
('Basic 4', 'English Language', 'english', 'Reading', 'Vocabulary', 'B4.2.6.4', 'Use words appropriately for purpose, audience, context and culture', 'B4.2.6.4.3', 'Use words suitable for purpose, audience, context and culture in relation to type of texts (exposition/explanation)', 'Explain to children the key elements in all writing e.g. purpose, audience etc. These help to make the understanding of the text easy. That is, they play an integral part in the process. Guide learners to understand each key element.; Introduce learners to a variety of texts and registers which may be used in given situations. Have learners work in groups to write short texts on familiar topics.', 530),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.1', 'Process and comprehend level- appropriate texts', 'B4.2.7.1.1', 'Construct meaning from texts read', 'Select level-appropriate texts for learners.; Take learners through Before Reading activities such as picture walk, prediction and Before Reading questions etc. to elicit their prior knowledge.; Have learners use their previous knowledge/experience, contextual clues and While Reading questions to make meaning from the text as they read.; Provide After Reading questions to help learners make meaning from the text read.', 540),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.1', 'Process and comprehend level- appropriate texts', 'B4.2.7.1.2', 'Note and recall main ideas in a sequence', 'Using the SQ3R strategy, learners recall main ideas. Learners: S – Survey the text– (learners skim, by going through the chapter, noting heading/sub-heading and other understanding features. Q – Question – Generate questions about the content of the text. 3R Read – Read for more information. Recite – Retrieve information from meaning. Review – Go over the main ideas in the text using your own words.', 550),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.1', 'Process and comprehend level- appropriate texts', 'B4.2.7.1.3', 'Skim for main ideas in texts', 'Guide learners to scan/skim the text either for general or specific information as a preparation for detailed reading.', 560),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.1', 'Process and comprehend level- appropriate texts', 'B4.2.7.1.4', 'Read level-appropriate texts silently and closely for comprehension', 'Briefly discuss the need for silent reading.; Guide learners with pre-reading questions.; Assign them to read the text silently to find answers to the pre- reading questions. Note: Depending on the length of the text, it may be read in bits.', 570),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation', 'B4.2.7.2.1', 'Respond to a text with reasons', 'Identify and present points of view in a text.; Guide learners with questions to discuss the text and answer a variety of questions. They should state reasons for their points/ point of view.', 580),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation', 'B4.2.7.2.2', 'Make connections between a text and personal experiences/real life', 'Guide learners with questions e.g. applicative questions to connect the reading text with background knowledge.; Encourage learners to come up with their personal opinions and viewpoints.', 590),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.2', 'Apply critical reading, implied meaning, higher order thinking, judgment and evaluation', 'B4.2.7.2.3', 'Demonstrate awareness of the structure of texts (', 'e.g. introduction, body, conclusion); Guide learners to identify the parts of a text e.g. Introduction, Body and Conclusion.; They should summarise each part and after that, make a full summary of the text.', 600),
('Basic 4', 'English Language', 'english', 'Reading', 'Comprehension', 'B4.2.7.3', 'Demonstrate an understanding of the use of words and phrases as used in a text B4.2.7.3: Demonstrate an understanding of the use of words and phrases as used in a text', 'B4.2.7.3.1', 'Determine the contextual meaning of words and phrases', 'Phrases have their meaning different from the individual words. Guide learners to make the right meaning using the text to get the contextual meaning.', 610),
('Basic 4', 'English Language', 'english', 'Reading', 'Silent Reading', 'B4.2.8.1', 'Construct meaning from texts read', 'B4.2.8.1.1', 'Read silently and reasonably for meaning from level- appropriate texts', 'Learners read silently making reference to pictures, illustrations, etc. to make meaning of texts. Encourage learners to do independent work. Note: You may guide learners with questions to do this.', 620),
('Basic 4', 'English Language', 'english', 'Reading', 'Silent Reading', 'B4.2.8.1', 'Construct meaning from texts read', 'B4.2.8.1.2', 'Find meaning of words as used in context', 'Guide pupils to learn new words through the procedure below: − Write key words on the board, one at a time. − Have learners attempt to pronounce the word. − Model the pronunciation for learners to repeat. − From the passage, ask learners to write the sentence in which the new word is and read it out. − Use Think-Pair-Share strategy to have learners find meaning in context. − Have them think of other words that can replace these words. − Ask pupils to use the words in sentences. Note: You can vary the procedure in teaching new words.', 630),
('Basic 4', 'English Language', 'english', 'Reading', 'Silent Reading', 'B4.2.8.1', 'Construct meaning from texts read', 'B4.2.8.1.3', 'Answer questions based on the passage read', 'Precede questions with silent reading of the text.; In asking questions, follow the steps below: − Pose the question. − Give learners time to reflect. − Call a learner to answer the question.; Learners give accurate and specific answers to questions. (You could do it orally sometimes). They may read out portions of the text where the answers are found.; Ask different types of levels of questions.', 640),
('Basic 4', 'English Language', 'english', 'Reading', 'Fluency', 'B4.2.9.1', 'Read fluently to enhance comprehension', 'B4.2.9.1.1', 'Read grade- level texts at good pace, with accuracy and expression', 'Take learners through pre-reading, while-reading and after-reading activities.; In cases where text books are not available, teacher should use carefully selected grade-level appropriate texts.; As learners listen and follow in their books, read a paragraph or two aloud at a good pace, with accuracy and expression.; Have individuals take turns to practise reading aloud at a good pace, with accuracy and expression.', 650),
('Basic 4', 'English Language', 'english', 'Reading', 'Fluency', 'B4.2.9.1', 'Read fluently to enhance comprehension', 'B4.2.9.1.2', 'Use recognition strategies to confirm understanding of level-appropriate texts', 'As learners read the grade-level texts, attention should be given to the words, sentences and paragraphs. Use re-reading, vocabulary and right intonation to self-correct.', 660),
('Basic 4', 'English Language', 'english', 'Reading', 'Summarising', 'B4.2.10.1', 'Read and summarise passages read', 'B4.2.10.1.1', 'Summarise level-appropriate passages/texts orally', 'Learners read and re-read a text to identify the main idea in a given paragraph.; Guide learners with examples to restate information read in a few words.', 670),
('Basic 4', 'English Language', 'english', 'Reading', 'Summarising', 'B4.2.10.1', 'Read and summarise passages read', 'B4.2.10.1.2', 'Write short summary of a level-appropriate passage/text read', 'Guide learners to write a summary of the passages taking note of the main ideas.; In pairs or groups, learners summarise specific paragraphs of a passage to be presented to the class.', 680),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B4.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B4.3.1.1.1', 'Identify and use nouns to identify people, animals, events and objects', 'Have learners read simple sentences having names of people, animals, events and objects from the board.; Put learners in groups to identify the names of people, animals, events and objects as nouns.; Have learners form sentences with names of people, animals, events and objects and underline these nouns in the sentences.; Have them note that common nouns start with small letters.; Have learners identify common nouns from paragraphs/passages.', 690),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B4.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B4.3.1.1.2', 'Identify and use: proper nouns', '– refer to cities and countries and), Common nouns a. Proper Nouns; Have learners read simple sentences having names of cities and countries from the board.; Put learners into groups to identify the names of cities and countries on a globe or map.; Learners form sentences with names of other cities and countries.; Have learners identify proper nouns from paragraphs/passages.', 700),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B4.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B4.3.1.1.3', 'Identify and use collective nouns to refer to a group of objects and people', 'Have learners read sentences containing collective nouns e.g. team of players, a class of, a swarm of bees, a troop of monkeys, a flock of sheep, a bunch of keys.; Explain to learners that collective nouns behave like singular nouns. Therefore, they are used with singular verbs.; Provide the collective nouns and their groups for learners to identify. Let them form sentences using the collective nouns. e.g. i. A bunch of keys is on the table. ii. A team of players is running around the field.; Have learners form sentences with collective nouns.', 710),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Nouns', 'B4.3.1.1', 'Apply knowledge of different types of nouns in communication', 'B4.3.1.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Write sentences containing abstract nouns on the board.; Have learners take turns to read them and identify the nouns.; Explain abstract nouns as names of things that cannot be seen, felt, nor touched e. g. air, beauty, peace, etc.; Have learners give examples of abstract nouns, use them in sentences and underline them.; Learners identify concrete and abstract nouns from short paragraphs/passages.', 720),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B4.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B4.3.2.1.1', 'Identify and use the definite and indefinite articles “a” and “an” to refer to a person, animal, event, time or objects in general Note: Teacher should use level-appropriate vocabulary to teach the articles', 'Have learners read sentences containing articles. − Indefinite articles: e.g. I bought an orange. a car, a sheep, a tree, an apple, an orange, an egg, etc. − Definite article: I put the book on the table.; Use several examples to explain the use of the definite and indefinite articles.; Nouns such as music, soup, soap, do not require any determiners. Thus show further that it is possible to say: i. I love music. ii. I enjoy soup.; Put learners into small groups to form sentences with a, an, the.', 730),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B4.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B4.3.2.1.2', 'Identify and use quantifiers to show quantities − Numerals (cardinals: one, two) − Some, few/little, etc. − No, all/every', 'Have learners read sentences with quantifiers from the board. e. g. some, few/little, one, two, No, all /every etc. Put some pictures on the wall.; Use more examples to show that these quantifiers are used with non-countable nouns: few, little, etc. e. g. little water, little bread, few books, etc.; Have learners write sentences using quantifiers e.g. many books, a piece of chalk and identify them from given sentences/texts.', 740),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B4.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B4.3.2.1.3', 'Identify and use possessive pronouns to show possession − My, your, his, etc', 'Write sentences with possessive pronouns on the board and have learners read them. e.g. i. I gave my pen to John. ii. The women went to their rooms.; Have learners form oral sentences using possessive pronouns.; Put them into groups to use possessive pronouns to write sentences and underline the possessive pronouns.', 750),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B4.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B4.3.2.1.4', 'Identify and use demonstratives: − this/that, these/those', 'Write sentences with demonstratives. i. This boy is from Cape Coast.; Have learners read the sentences aloud.; Explain to learners the use of the demonstratives. e.g. − “this” and “that” are used before singular nouns e.g. this girl, that girl.', 760),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Determiners', 'B4.3.2.1', 'Apply knowledge of different types of determiners in communication', 'B4.3.2.1.5', 'Identify and use interrogative determiners “which, whose”', '– to find out about specific persons or objects; Present several examples in context and explain their use.; Have learners identify them in sentences and short texts.; Let them use the interrogatives in their own sentences. e. g. Which house is bigger?', 770),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Pronouns', 'B4.3.3.1', 'Apply knowledge of different types of pronouns in communication', 'B4.3.3.1.1', 'Identify and use different types of pronouns: − “Personal”', '– to identify people, activities and objects − “Interrogative” – “who, what” to find out a person’s identity, specific information about a person, time, objects or events i. Personal pronouns – I, You, He/She, We, etc.; Write sentences with personal pronouns. e. g. You are late.; Provide learners with a variety of practice activities. ii. Interrogative pronouns – Who, What, Where, etc.; Introduce interrogative pronouns with several examples in context.; Provide a passage and have learners identify interrogative pronouns.; Let learners use interrogative pronouns in sentences.', 780),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adjectives', 'B4.3.4.1', 'Apply the knowledge of adjectives in communication', 'B4.3.4.1.1', '1. Use adjectives to make comparison e. g: − fast/slow (Ama is fast but Kofi is slow.) − good/bad − fast/faster − slow/slower • Revise adjectives. Have learners identify adjectives in sentences and use them in sentences of their own. • Introduce regular adjective forms: - Regular adjectives form their imperative by adding er', 'e.g. small–smaller, big–bigger, etc.; Assist learners with examples to use comparative adjectives appropriately. e.g. i. Ama is taller than Kwesi. ii. This ruler is longer than that one.; Learners form sentences with the comparative forms of adjectives.', 790),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.1', 'Use different types of verbs: − Main verb − Helping verb (primary auxiliary and modal auxiliary) Main verbs', 'Have learners revise verbs by reading sentences from the board and identifying the verbs.; Have learners write sentences with given verbs. Auxiliary verbs; Let learners read sentences with auxiliary verbs. e.g. i. The boy is going to school. ii. The girls are reading. Note: An auxiliary verb is also known as a helping verb e.g. is, are, am, was, were; Have learners use auxiliary verbs in sentences and underline them.', 800),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.2', 'Use appropriate subject-verb agreement − Singular/plural', 'Revise nouns and verbs with simple examples.; Through discussion and examples help learners to realise rules that govern sentence formation: - A Singular subject goes with singular verb. e. g. The boy is in the room. - A Plural subject goes with a plural verb. e. g. The girls are happy. - Collective nouns take singular verb. e. g. The team is playing tomorrow.; Provide sentences for groups to identify the subjects and verbs.; Have learners write their own sentences to be presented to the class.', 810),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.3', 'Use the simple present form of verbs in sentences: − For habitual actions − For timeless and universal statements − For facts which may change or hold true indefinitely − For instantaneous present − For scheduled future actions', 'Using several examples demonstrate the use of the simple present form of verbs in the sentences (for habitual actions/ for timeless and universal statements): − Habitual actions. e.g. i. Esi reads every day. ii. Joe sweeps every morning.; Create situations for learners to use verbs to express habitual actions. e.g. Tell the class what you do every morning. − Timeless and universal statements. e.g. i. The sun rises in the east and sets in the west. ii. Ghana is in Africa.; Provide ample practice using language drills.', 820),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.4', 'Use regular form of the simple past tense of verbs − Regular', 'e.g. play-played; Revise main and auxiliary verbs by having learners identify them in sentences.; Introduce learners to the concept of regular verbs: - Regular verbs form their past tense by adding “d” or “ed” e.g. play= played, walk= walked, bake= baked', 830),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.5', 'Use the simple past form of verbs for: − Completed actions or events − Regular actions in the past', 'Revise the simple present tense by having learners say what they do regularly e.g. every morning.; Learners listen to a simple story in which several completed actions have occurred.; Discuss the story and have learners identify the verbs.; Learners engage in a conversion drill for practice.; Learners write simple sentences in the past tense using (both regular and irregular verbs).', 840),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.6', 'Use the simple present form of verbs to relate past events to the present', null, 850),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Verbs', 'B4.3.5.1', 'Apply the knowledge of verbs in communication', 'B4.3.5.1.7', 'Use the imperative form of the verb to give commands or orders, make suggestions', 'Use situations to demonstrate commands.; Provide situations for learners to give and respond to commands in parts or groups.', 860),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adverbs', 'B4.3.6.1', 'Apply the knowledge of different types of adverbs in communication', 'B4.3.6.1.1', 'Use adverbs of time and place appropriately', 'Revise adverbs by having learners identify them in sentences.; Present adverbs of place in context.; Provide practice in identifying and using adverbs. For practice use questions and answers, and illustrations.; Drill learners to practise the appropriate use of adverbs of place. e.g. i. Where is the cat? The cat is here. ii. Where is Kojo? Kojo is outside.; Examples of adverbs of place are: here, there, outside, inside, etc.; Ask learners to use adverbs of place to form correct sentences.', 870),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Adverbs', 'B4.3.6.1', 'Apply the knowledge of different types of adverbs in communication', 'B4.3.6.1.2', 'Use adverbs of time to modify verbs', 'Present adverbs of place in context. Examples of adverb of time are yesterday, today, tomorrow, etc.', 880),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Idiomatic Expressions', 'B4.3.7.1', 'Understand and use idiomatic expressions appropriately in speech and in writing', 'B4.3.7.1.1', 'Use idiomatic expressions appropriately in communication', 'Present examples of idiomatic expressions in context.; Discuss each with learners to bring out it’s meaning.; Have learners use the expressions they have learnt in sentences guided with further examples.; Put learners into groups to determine the meaning of given idiomatic expressions in context.', 890),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Conjunctions', 'B4.3.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B4.3.8.1.1', 'Identify and use simple conjunctions - and, but, or, nor - to link: - similar ideas - contrasting ideas, show choices/express alternatives', 'Introduce the conjunctions one at a time in context.; Elicit examples of sentences with conjunctions from learners.; Put on cards simple sentences. e.g. i. Esi is tall. Ama is short. ii. Esi is tall but Ama is short.; Use Combination Drill for learners to practise the use of conjunctions. e.g. i. Learner A: I bought a pen… ii. Learner B: I bought a pen and a notebook. iii. Learner C: I will eat fufu…… Learner D: I will eat fufu or kenkey.', 900),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Modals', 'B4.3.9.1', 'Apply the knowledge of modals in speech and in writing', 'B4.3.9.1.1', 'Use modals to express a variety of meanings: − can: conveys ability − may: asks for permission, expresses politeness, possibility − must: obligation or compulsion, necessitys − shall / will: prediction, intention, determination etc. − could: tentativeness, politeness − would: politeness − might: possibility − should: obligation − used to: for past activities or events − have to, ought to and need to: for obligation', 'Introduce the modals one at a time.; Have learners read sentences containing modals.; Learners use modals to form sentences and choose the right modals to fill the gaps.; Use drills to give practice. Note: Modals come before the main verbs in sentences.', 910),
('Basic 4', 'English Language', 'english', 'Grammar Usage at Word and Phrase Levels', 'Prepositions', 'B4.3.10.1', 'Apply the knowledge of prepositions in oral and written communication', 'B4.3.10.1.1', 'Use prepositions to convey a variety of meanings: − Direction', 'e.g. along − Period of Time − Purpose − Possession − Comparison e.g. taller than; Have learners describe the positions of classroom objects using such sentences as: i. The clock is on the wall. ii. The cupboard is in the corner. iii. The waste paper basket is under the table.; Briefly explain the functions of prepositions.; Introduce a Question and Answer drill to give learners practice. Learner A: Where is your pen? Learner B: It is on the table.; Write some of learners’ answers on the chalkboard and guide them to identify the prepositions. Note: Ensure that the following prepositions are used: − Direction= towards the mountain − Time = at six o’clock − Purpose = for, in order to − Possession= for, to − Comparison= than − Support or opposition = for you, against me', 920),
('Basic 4', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B4.4.2.1', 'Copy and rewrite sentences correctly', 'B4.4.2.1.1', 'Write clearly using joined letters of consistent size', 'Stage 1 : Write letters with a flick e.g. a, t, m, n, w, d; Stage 2: Join pairs of letters. e.g. at, am, et, de; Stage 3: Join the letters of a word. e.g. and , kettle, can, catch kettle, can, catch, and; Stage 4: Copy sentences and passages Procedure:; Demonstrate the exercise; Give practice; Give exercise; Provide feedback', 930),
('Basic 4', 'English Language', 'english', 'Writing', 'Penmanship and Handwriting', 'B4.4.2.1', 'Copy and rewrite sentences correctly', 'B4.4.2.1.2', 'Use simple sentences clearly and correctly', 'Begin proper nouns with capital letters in sentences. e.g. i. Accra is the capital of Ghana. ii. Esi went to Mfantsiman School.; Have learners read out sentences and identify proper nouns.; Let learners note the use of capital letters.; Have them copy the sentences into their exercise books.; Present and give practice on the named marks of punctuation marks similarly: e.g. i. She is a teacher. ii. How are you? iii. I bought a pencil, ruler and a book.; • Discuss the importance of these punctuation marks. i. Full stop (.) marks the end of a sentence. ii. Question mark (?) is used to ask questions. iii. Comma (,) is used when listing items.', 940),
('Basic 4', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B4.4.6.1', 'Develop, organise and express ideas cohesively in writing for a variety of purposes, audience, and contexts', 'B4.4.6.1.1', 'Choose appropriate ways and modes of writing for a variety of purposes, audiences, and contexts, and organise facts, ideas and/or points of view in a way appropriate to the mode of delivery, using appropriate text features', 'Select sample essay types/texts showing a variety of modes of writing from learners'' readers and/teacher''s resource. e.g. i. Expository Writing – how something works. ii. Narrative – how something happened. iii. Description – how something/someone appears. iv. Argument – how an opinion can be stated and supported.', 950),
('Basic 4', 'English Language', 'english', 'Writing', 'Paragraph Development', 'B4.4.6.1', 'Develop, organise and express ideas cohesively in writing for a variety of purposes, audience, and contexts', 'B4.4.6.1.2', 'Identify the main idea and minor ideas/supporting details in a paragraph', 'Provide sample paragraphs that have main ideas and supporting details.; Discuss one of these and guide learners to identify the main and supporting ideas.; Have learners work in groups of four to read and identify the main idea and supporting ideas. Guide them with the questions: i. What is the paragraph talking about/What is the main idea in the paragraph? ii. Which sentence has the main idea? Which sentences say something about the main idea?', 960),
('Basic 4', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B4.4.9.1', 'Apply the skills and strategies for idea generation, selection, development, organisation and revision in writing', 'B4.4.9.1.1', 'Select a topic of choice on issues in the immediate environment, brainstorm and organise ideas before writing', 'Take learners through the writing process: Prewriting stage; Put learners in groups of four (4). Each member suggests a topic. Each group discusses it’s topics and selects one. Each team presents their topic to the class and writes it on the board.; Have groups plan their composition by identifying and discussing the purpose, audience and the context of the piece.; Invite groups to present their work and have the whole class give feedback.; Use learner strategies such as brainstorming to help learners generate ideas appropriate to the topic.; Have learners use graphic organisers to organise the ideas generated. e. g. Brainstorming; Brainstorming involves expressing one''s own views and ideas to contribute to resolve a problem.; The activity can be done as a whole class, in small groups or in pairs. The high-ability learners may take leading roles. Note: Do not evaluate learners'' ideas but accept and record each idea on the board. Assure them that they are not required to justify or explain the ideas they generate.', 970),
('Basic 4', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B4.4.9.2', 'Develop and express ideas coherently and cohesively in writing B4.4.9.3: Apply strategies for improving drafts for publishing', 'B4.4.9.2.1', 'Develop ideas into a one-paragraph draft using appropriate nouns or pronouns within and across sentences to aid cohesion and avoid ambiguity Writing stage', 'Have learners work independently to write a first draft. Advise learners to: i. Concentrate on getting ideas on paper, not to produce a perfect piece of writing. ii. Use the ideas generated but feel free to add new ideas that occur to them as they write.; Be sure their writing has a beginning, middle and an ending.', 980),
('Basic 4', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B4.4.9.3', 'Apply strategies for improving drafts for publishing', 'B4.4.9.3.1', 'Review and revise the one-paragraph draft taking out irrelevant details', 'Have pupils revise their first draft. Ask them to set aside their first draft for a while and return to it to read over slowly and critically, and reread it several times.; Have learners use these questions as a revision guide: i. Is my topic interesting? ii. Does the beginning catch the reader’s attention? iii. Are the ideas easy to understand? iv. Do all the sentences say something about the topic?; Encourage learners to make as many changes as necessary to improve their work.', 990),
('Basic 4', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B4.4.9.3', 'Apply strategies for improving drafts for publishing', 'B4.4.9.3.2', 'Edit/proofread draft, checking capitalisation, usage of punctuation and spelling', 'Have learners proofread the revised draft of their writing with focus on the conventions of punctuation, capitalisation, spellings, etc.; Let them do peer editing. Learners check their partners’ writing for errors (punctuations, spelling, etc.); Have learners write a neat final copy and read it once again to check for errors.', 1000),
('Basic 4', 'English Language', 'english', 'Writing', 'Writing as a Process', 'B4.4.9.3', 'Apply strategies for improving drafts for publishing', 'B4.4.9.3.3', 'Display writing piece for other peers to read', 'Have learners publish their work by preparing and showing it to others in small groups or in pairs. Allow them to post their work on the notice board or show it to all other learners in the class one after the other. Encourage learners to share their work with their family members. Have them keep their work in their portfolios. They may type their work and publish it in the class magazine.', 1010),
('Basic 4', 'English Language', 'english', 'Writing', 'Narrative Writing', 'B4.4.10.1', 'Narrate situations, express feelings and convey point of view about the world/ or fictional world', 'B4.4.10.1.1', 'Write about real or imagined experiences or events following story structure (beginning, middle and ending), using appropriate nouns or pronouns within and across sentences to aid cohesion. i. Describing the setting and developing the plot (events in the story). ii. Describing characters with elaboration. iii. Using first and third persons', 'Guide learners to narrate an event they participated in e.g. my first day at the national theatre. Learners tell the story sequentially: beginning, middle and end. (Learners are grouped to write their own story based on a chosen experience agreed on by all. Let them build a mind map to guide their writing.); Let learners use adjectives and adverbs in describing the physical appearance and state of their characters.; Guide them with examples to write from the first person point of view to start with and later change the same story to read from the third person point of view.; Learners edit their work first in their groups, then across groups. Let learners then publish their stories on the class notice board so each group can read another’s story.', 1020),
('Basic 4', 'English Language', 'english', 'Writing', 'Creative/Free Writing', 'B4.4.11.1', 'Create texts', 'B4.4.11.1.1', 'Write freely about topics of choice in their immediate environment', 'Have learners, in pairs, think-pair-share and choose a topic from their immediate environment they will want to write about.; Guide learners to brainstorm and generate ideas.; Have learners organise their ideas and write their first draft.; They then peer edit their work.; Have them present their work for class discussion and correction.; They then write the final draft and display their work for their peers to read.', 1030),
('Basic 4', 'English Language', 'english', 'Writing', 'Creative/Free Writing', 'B4.4.11.1', 'Create texts', 'B4.4.11.1.2', 'Write poems and imaginative, narrative stories and illustrate them', 'Guide learners to read a poem and let them write a parallel one to start as group presentations.; Learners then choose topics and write a four- or five-line poem and illustrate it.; Guide them to edit each other’s work by exchanging with other groups.; Have groups present their work to the class.; Encourage reactions from the class. Imaginative narrative; Guide learners through relevant questions to write imaginative stories on topics/themes of their choice.', 1040),
('Basic 4', 'English Language', 'english', 'Writing', 'Descriptive Writing', 'B4.4.12.1', 'Demonstrate knowledge of descriptive words/expressions in writing', 'B4.4.12.1.1', 'Use descriptive words/expressions to describe places, personal experiences and events Note: The teacher should consider level-appropriate vocabulary and grammar', 'Revise adjectives by having learners describe familiar people, objects and places in their environment.; Learners in their groups talk about interesting places they have visited.; Guide them to describe places of their choice using knowledge of adjectives.; Have them do peer editing and share their work with the class.; They repeat the procedure above to describe events, situations and personal experiences.', 1050),
('Basic 4', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B4.4.13.1', 'Support an opinion in writing', 'B4.4.13.1.1', 'Support opinions with simple sentences', 'Present a motion to learners. e. g. A doctor is more important than a farmer.; Discuss the meaning and implication of the motion with pupils and invite them to take a stand either for or against the motion.; Put learners into two groups: for the motion and against the motion and write down what they think about it.; Groups read out their opinions to the class for discussions.', 1060),
('Basic 4', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B4.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence', 'B4.4.13.2.1', 'Introduce claim(s) and support them with clear reasons and relevant evidence', 'Working in groups (as in B4.7.1.1), learners provide reasons for the opinions they hold on a topic.; Guide groups to provide evidence for the opinions they hold.; Have groups present their work for discussions.', 1070),
('Basic 4', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B4.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence', 'B4.4.13.2.2', 'Use words, phrases, and clauses to clarify the relationships between claim(s) and reasons', 'Lead learners to discuss appropriate language for arguments e. g. use of adjectives in their various forms.; You may read out model argumentative essays to guide learners as they listen carefully to identify useful phrases, clauses and expressions.', 1080),
('Basic 4', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B4.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence', 'B4.4.13.2.3', 'Establish and maintain a formal style', 'Using models, discuss the basic structure of an argumentative piece: − Introduction; − Reasons for the stand taken; − Conclusion.; Have groups present full compositions using this structure for class discussions.', 1090),
('Basic 4', 'English Language', 'english', 'Writing', 'Argumentative/Persuasive Writing', 'B4.4.13.2', 'Write arguments to support claims with clear reasons and relevant evidence', 'B4.4.13.2.4', 'Provide a concluding statement that follows from argument presented', 'Have learners listen to a debate on a familiar topic.; Learners in groups discuss the debate.; Teach the features of a debate. Guide learners to select a debatable topic. Divide the class into two to go through the writing process to prepare to debate the topic.', 1100),
('Basic 4', 'English Language', 'english', 'Writing', 'Expository/Informative Writing', 'B4.4.14.1', 'Write informative essays', 'B4.4.14.1.1', 'Write words giving information about family', 'Guide learners with a model to talk about themselves. This is a whole class discussion with individual learners saying things about themselves.; Let learners write about themselves. In pairs learners edit each other’s work and identify words and sentences that give information about the partner which they did not know previously.; In groups learners research about their school and write a short history about it.', 1110),
('Basic 4', 'English Language', 'english', 'Writing', 'Expository/Informative Writing', 'B4.4.14.2', 'Write an event of the day', 'B4.4.14.2.1', 'Write picture events about personal experiences and make radio/TV presentations', 'Let learners watch TV news at home and write their own news from the pictures they see.; Put learners into groups. Let them brainstorm and write activities of the day.; Let each group choose an interesting event and write the news to broadcast to the class.; Let each group choose one person to present the news.; Help learners to organise a radio or TV talk show.', 1120),
('Basic 4', 'English Language', 'english', 'Writing', 'Letter Writing', 'B4.4.15.1', 'Write informal letters on given topics', 'B4.4.15.1.1', 'Write to friends about personal experiences using appropriate letter formats', 'Present samples of friendly letters to learners.; Let learners read samples in groups and identify important features of friendly letters.; Discuss these features with learners.; Each group writes a friendly letter (about their personal experiences) showing the important features.', 1130),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Punctuation', 'B4.5.2.1', 'Show understanding of how punctuations are used appropriately in writing', 'B4.5.2.1.1', 'Use the comma: − before and after "Yes" and "No" in sentences − after addressing a person,', 'e.g. Kofi, can you help me?; Provide learners with sample texts for them to identify the target punctuation marks. e.g. Yes, please. No, thank you. Kofi, can you help me?; Give them practice in using the punctuation marks. They may copy and punctuate unpunctuated sentences and short paragraphs.; Have them write sentences to demonstrate understanding of the use of the comma before and after "Yes" and "No" in sentences; - after addressing a person.', 1140),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Naming words/ Nouns', 'B4.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B4.5.3.1.1', 'Identify and use nouns in sentences to identify people, animals, events and objects', 'Have learners read simple sentences with names of people, animals, events and objects on the board.; Put learners in groups to identify the names of people, animals, events and objects as nouns.; Have learners form sentences with names of people, animals, events and objects and underline these names/nouns in the sentences.; Have them note that common nouns start with small letters.; Have learners identify common nouns from paragraphs/passages.', 1150),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Naming words/ Nouns', 'B4.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B4.5.3.1.2', 'Identify and use: − Proper nouns', '– refer to cities and countries − Common nouns − Proper nouns; Have learners read simple sentences with names of cities and countries from the board.; Put learners into groups to identify the names of cities and countries.; Have learners identify proper nouns from paragraphs/passages.; Have learners form sentences with names of other cities and countries.', 1160),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Naming words/ Nouns', 'B4.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B4.5.3.1.3', 'Identify and use collective nouns to refer to a group of objects and people', 'Have learners read sentences containing collective nouns e.g. a team of players, a school of fish, a swarm of bees, a troop of monkeys, a flock of sheep, a bunch of keys.; Explain to learners that collective nouns behave like singular nouns. Therefore, they are used with singular verbs.; Provide collective nouns and their groups for learners to identify. Let them form sentences using the collective nouns.', 1170),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Naming words/ Nouns', 'B4.5.3.1', 'Apply knowledge of different types of nouns in communication', 'B4.5.3.1.4', 'Identify and use abstract nouns to refer to concepts and ideas', 'Revise common and proper nouns.; Write sentences containing abstract nouns on the board.; Have learners take turns to read them and identify the nouns.', 1180),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B4.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B4.5.4.1.1', 'Use the singular and plural subjects and the verb forms that go with them', 'Revise the simple present form of verbs and their use to agree with the subject they follow.; Have learners do an activity: e. g. Write a letter to your friend telling him/her what you and your siblings do after school. Learners read their friendly letters in pairs.; Guide learners to correct the wrong use of subjects and their appropriate verb forms that go with them if any. e.g. we eats – we eat.; Have learners do peer editing to identify and correct errors.', 1190),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B4.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B4.5.4.1.2', 'Demonstrate the use of the simple past form in speech and in writing to express past conditions', 'Revise the simple past tense (both regular and irregular verbs).; Assign learners to do an activity e.g. let learners, in small groups, re-write the letters they wrote previously in the simple past tense (Refer to', 1200),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Action Words', 'B4.5.4.1', 'Demonstrate understanding of verbs in everyday language', 'B4.5.4.1.3', 'Use the present perfect form of verbs to relate past events to the present', 'Learners in pairs plan what they will do during the next weekend.; They put their plan into writing using modal auxiliaries.; Let two pairs come together to form bigger groups to edit their work one after the other.; Pairs of learners read their work to the class for discussion.', 1210),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Qualifying Words – Adjectives', 'B4.5.5.1', 'Demonstrate understanding of adjectives in speech and in writing', 'B4.5.5.1.1', 'Use adjectives to make comparisons', 'e.g. − fast /slow − good/bad − fast/faster − slow/slower; Guide learners with several examples and situations to identify the comparative forms of adjectives in sentences, e.g. Ama is fast but Kofi is slow.; Have learners identify adjectives in a given passage.; Let learners write sentences using comparative and superlative forms of adjectives.', 1220),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Qualifying Words – Adjectives', 'B4.5.5.1', 'Demonstrate understanding of adjectives in speech and in writing', 'B4.5.5.1.2', 'Differentiate between how the comparative and superlative adjective forms are used in sentences', 'Guide learners with examples to talk about their siblings using adjectives.; In pairs, learners write two to three sentences to describe their classmates using the three forms of adjectives.; Two pairs put their work together and do a comparison. Let them share their work with other groups.', 1230),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Adverbs', 'B4.5.6.1', 'Understand and use adverbs correctly in speech and in writing', 'B4.5.6.1.1', 'Use adverbs to talk about when and where the action of a verb took place', 'Guided with examples, let learners narrate events using adverbs to describe the place and time of occurrence.; Introduce drills to provide oral practice.; Learners in group go on a field trip/excursion to e.g. a tourist centre.; Let them write and present their stories to demonstrate their knowledge of adverbs of place and time.', 1240),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple Prepositions', 'B4.5.7.1', 'Apply the knowledge of prepositions in oral and written communication', 'B4.5.7.1.1', 'Use prepositions to convey a variety of meanings: − Direction,', 'e.g. up − Period of Time, e.g. for − Purpose, e.g. to − Possession, of − Comparison e.g. taller than; Have learners describe the positions of classroom objects using such sentences.', 1250),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Conjunctions', 'B4.5.8.1', 'Apply the knowledge of conjunctions in speech and in writing', 'B4.5.8.1.1', 'Identify and use conjunctions', '– and, but, or, nor – to link: - similar ideas - contrasting ideas - express alternatives Note: Learners are to consolidate the knowledge of conjunctions acquired in Strand 3: Grammar Usage at Word and Phrase Levels.; Guide learners to give examples of sentences demonstrating their knowledge of conjunctions. e.g. i. Musa and Kuma are good friends. ii. Kwame is hard working but Abena is lazy.; Guide learners in groups to join sentences using coordinating conjunctions on a topic. e. g. A visit to an interesting tourist site.; Guide them to edit each other’s work by exchanging with other groups.; Let learners talk about the differences in their stories.', 1260),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple, Compound and Complex Sentences', 'B4.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences', 'B4.5.9.1.1', 'Identify subjects and verbs in simple sentences', 'Give learners an extract from a comprehension passage.; Guide them to identify the simple sentences. Let them identify subjects and verbs in each sentence.; Let learners write an event they have participated in.; Learners edit their work to demonstrate their knowledge of subject and predicate.', 1270),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Using Simple, Compound and Complex Sentences', 'B4.5.9.1', 'Apply knowledge of grammatical rules to form words, phrases and sentences', 'B4.5.9.1.2', 'Construct simple sentences correctly', 'Learners construct simple sentences.; Write some of the sentences on the board to guide the discussions on subjects and verbs.; Show a large poster of people doing various activities.; Assign learners to build a paragraph on the picture paying attention to subject and predicate. They use a line to divide each sentence into the subject and predicate.; The groups edit and publish the work. Each member keeps a copy.', 1280),
('Basic 4', 'English Language', 'english', 'Using Writing Conventions/ Grammar Usage', 'Spelling', 'B4.5.10.1', 'Spell words accurately', 'B4.5.10.1.1', 'Use invented spelling to increase fluency and free writing', 'Let learners spell given words with invented spellings. Each group tries to write the correct spelling. The group to get the highest number of words spelt correctly is regarded as the Spelling Champion for the work.; Give learners the meanings of words to identify and spell the words.; Learners use the words they have spelt in sentences of their own.; Select registers of various subjects/topics (shopping, transportation, agriculture).; Guide learners to spell the appropriate vocabulary used in that context.; Let learners use the words in writing a short paragraph describing or narrating that activity (shopping, travelling by bus, making a farm, catching fish).', 1290),
('Basic 4', 'English Language', 'english', 'Extensive Reading', 'Building the Love and Culture of Reading', 'B4.6.1.1', 'Read widely for pleasure, personal development, and demonstrate independent reading and learning in the literary content areas', 'B4.6.1.1.1', 'Read a variety of age- and level appropriate books and present a-two-paragraph summary of each book read', 'Guide learners to choose and read independently books of their choice during the library period.; Learners think-pair-share their stories with peers.; Ask each learner to write a-two-paragraph summary of the book read.; Invite individuals to present their work to the class for feedback.', 1300);
